CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY,name text NOT NULL,plan text NOT NULL DEFAULT 'pilot' CHECK(plan IN ('pilot','basic','pro')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','read_only','suspended')),created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO tenants(id,name) VALUES('00000000-0000-4000-8000-000000000001','Moldaê') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS app_users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES app_users(id),role text NOT NULL CHECK(role IN ('owner','viewer')),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_users(id),tenant_id uuid NOT NULL REFERENCES tenants(id),expires_at timestamptz NOT NULL,last_seen timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_tokens(token_hash text PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('setup','invite','reset')),tenant_id uuid REFERENCES tenants(id),email text,role text CHECK(role IN ('owner','viewer')),expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_attempts(bucket text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id uuid PRIMARY KEY,name text NOT NULL UNIQUE,tenant_id uuid NOT NULL REFERENCES tenants(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid REFERENCES app_users(id),action text NOT NULL,entity_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integration_connections(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),provider text NOT NULL,status text NOT NULL DEFAULT 'not_connected',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider));
